/// Task 1:
/// Given a non-empty collection of dtypes, return a dtype from it with maximum precedence.
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Since input is non-empty, safe to unwrap after max_by_key.
    types.into_iter()
        .max_by_key(|dt| dt.precedence())
        .unwrap()
}

/// Task 2:
/// Given two collections: array_types and scalar_types,
/// return an Option<DType> as described in the problem.
///
/// - If only array_types given, return max precedence from array_types.
/// - If only scalar_types given, return max precedence from scalar_types.
/// - If both given, compute max from each, compare kinds:
///     If kind equal, return max from array_types,
///     else return max from scalar_types.
/// - If both empty, return None.
pub fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let max_array = array_types.into_iter().max_by_key(|dt| dt.precedence());
    let max_scalar = scalar_types.into_iter().max_by_key(|dt| dt.precedence());

    match (max_array, max_scalar) {
        (Some(a), None) => Some(a),
        (None, Some(s)) => Some(s),
        (Some(a), Some(s)) => {
            if a.kind() == s.kind() {
                Some(a)
            } else {
                Some(s)
            }
        }
        (None, None) => None, // Both empty input, per problem at least one non-empty, but safe
    }
}

