        assert_eq!(DType::Object.kind(), 'O');

        assert_eq!(DType::Bool.precedence(), 0);
        assert_eq!(DType::Int64.precedence(), 4);
        assert_eq!(DType::UInt64.precedence(), 8);
        assert_eq!(DType::Float32.precedence(), 9);
        assert_eq!(DType::Complex64.precedence(), 11);
        assert_eq!(DType::Object.precedence(), 13);
